sect1.programlisting:
EXPORT showValue() := MACRO
    IMPORT #$;
    OUTPUT(#$.value);
ENDMACRO;

EXPORT showChildValue() := MACRO
    IMPORT childModule FROM #$;
    OUTPUT(childModule.value);
ENDMACRO;

EXPORT formatValue(input) := FUNCTIONMACRO
    IMPORT #$.^.format AS formatter;
    RETURN formatter.formatValue(input);
ENDMACRO;
